describe('GET latest: the App update check (public)', () => {
  type Fixture = { version: string } & Record<string, string | number | Date>
  const check = (query: object) => request(app.getHttpServer()).get(`${URL}/latest`).query(query)
  const answer = async (version: string, nativeVersion = version, platform = 'android') =>
    (await check({ platform, version, nativeVersion }).expect(200)).body.data
  /** only these rows (SQL: no @Idempotent between the cases); android wgt unless given */
  const rows = async (...list: Fixture[]) => {
    await ds.query('DELETE FROM cfg_app_version WHERE id > ?', [lastId])
    for (const r of list)
      await insertRow(ds.manager, 'cfg_app_version', {
        platform: 'android',
        package_kind: 'wgt',
        url: `https://example.com/${r.version}`,
        ...r,
      })
  }
  /** 1.2.0 is a wgt for native 1.1.0 and up: the full 1.1.0 must come first */
  const STANDARD: Fixture[] = [
    { version: '1.0.1' },
    { version: '1.1.0', package_kind: 'full', notes: 'new base' },
    { version: '1.2.0', native_min: '1.1.0' },
  ]
  const offer = (
    version: string,
    packageKind: string,
    force = false,
    notes: string | null = null,
  ) => ({ version, packageKind, url: `https://example.com/${version}`, force, notes })

  afterAll(async () => {
    await setParam(APP_UPDATE_PARAMS.enabled, 'false')
    await setParam(APP_UPDATE_PARAMS.reviewVersion, '')
  })

  it('off by default: 200 null without a token; on: the update (route not taken by :id)', async () => {
    await rows(...STANDARD)
    expect(await params.get(APP_UPDATE_PARAMS.enabled)).toBe('false')
    expect(await answer('1.0.0')).toBeNull()
    await setParam(APP_UPDATE_PARAMS.enabled, 'true')
    expect(await answer('1.0.0')).toEqual(offer('1.1.0', 'full', false, 'new base'))
  })

  it('a wgt needs native_min: native 1.1.0 gets the 1.2.0 wgt, up to date gets null', async () => {
    await rows(...STANDARD)
    expect(await answer('1.1.0')).toEqual(offer('1.2.0', 'wgt'))
    // resources already 1.1.0 on an old base: the wgt does not fit, nothing newer fits
    expect(await answer('1.1.0', '1.0.0')).toBeNull()
    expect(await answer('1.2.0', '1.1.0')).toBeNull()
    expect(await answer('1.2', '1.1')).toBeNull()
  })

  it('the native version in store review gets no wgt; other native versions still do', async () => {
    await rows(...STANDARD)
    await setParam(APP_UPDATE_PARAMS.reviewVersion, '1.1.0')
    expect(await answer('1.1.0')).toBeNull()
    expect(await answer('1.1.0', '1.1.5')).toEqual(offer('1.2.0', 'wgt'))
    // a full package is still offered to it
    await rows(...STANDARD, { version: '2.0.0', package_kind: 'full' })
    expect(await answer('1.1.0')).toEqual(offer('2.0.0', 'full'))
    await setParam(APP_UPDATE_PARAMS.reviewVersion, '')
  })

  it('invalid review versions do not suppress a wgt', async () => {
    await rows(...STANDARD)
    await setParam(APP_UPDATE_PARAMS.reviewVersion, 'v1.2.0')
    expect(await answer('1.1.0', '3.2.0')).toEqual(offer('1.2.0', 'wgt'))
    await setParam(APP_UPDATE_PARAMS.reviewVersion, '1.1.0-beta')
    expect(await answer('1.1.0', '1.1.0')).toEqual(offer('1.2.0', 'wgt'))
    await setParam(APP_UPDATE_PARAMS.reviewVersion, '')
  })

  it('force: any forced release above the client, even one it skips', async () => {
    await rows({ version: '1.0.1', is_forced: 1 }, { version: '1.2.0' })
    expect(await answer('1.0.0')).toEqual(offer('1.2.0', 'wgt', true))
    expect(await answer('1.0.1')).toEqual(offer('1.2.0', 'wgt', false))
  })

  it('disabled and deleted rows, other platforms and lower versions are ignored', async () => {
    await rows(
      ...STANDARD,
      { version: '1.3.0', package_kind: 'full', enabled: 0 },
      { version: '1.4.0', package_kind: 'full', deleted_at: new Date() },
      { version: '9.0.0', package_kind: 'full', platform: 'ios' },
    )
    expect(await answer('1.1.0')).toEqual(offer('1.2.0', 'wgt'))
    expect(await answer('1.2.0')).toBeNull()
    expect(await answer('1.0.0', '1.0.0', 'ios')).toEqual(offer('9.0.0', 'full'))
    expect(await answer('9.0.0', '9.0.0', 'ios')).toBeNull()
  })

  it('400: unknown platform, non-numeric versions, a missing native version', async () => {
    for (const query of [
      { platform: 'web', version: '1.0.0', nativeVersion: '1.0.0' },
      { platform: 'android', version: '1.x', nativeVersion: '1.0.0' },
      { platform: 'android', version: '1.0.0', nativeVersion: '' },
      { platform: 'android', version: '1.0.0' },
    ]) {
      const res = await check(query)
      expect({ query, code: res.body.code }).toEqual({ query, code: Err.VALIDATION_FAILED.code })
    }
  })
})
